package com.cloudinfra.storage.encryption;

import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.MessageDigest;
import java.util.Arrays;
import java.util.Base64;
import java.util.logging.Logger;

/**
 * BlobDecryptionService handles decryption of user-uploaded encrypted blobs
 * in the cloud storage tier. Blobs are encrypted client-side before upload
 * and decrypted server-side for indexing/processing.
 *
 * Protocol: AES-128-CBC with PKCS5Padding
 * Format: [16-byte IV][ciphertext][32-byte HMAC-SHA256]
 */
public class BlobDecryptionService {

    private static final Logger LOG = Logger.getLogger(BlobDecryptionService.class.getName());
    private static final int IV_LENGTH = 16;
    private static final int HMAC_LENGTH = 32;
    private static final int BLOCK_SIZE = 16;

    private final byte[] encryptionKey;
    private final byte[] hmacKey;

    public BlobDecryptionService(byte[] masterKey) {
        // Derive separate keys for encryption and HMAC using HKDF-like derivation
        this.encryptionKey = deriveKey(masterKey, "encryption");
        this.hmacKey = deriveKey(masterKey, "integrity");
    }

    private byte[] deriveKey(byte[] master, String purpose) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(master);
            md.update(purpose.getBytes("UTF-8"));
            return Arrays.copyOf(md.digest(), 16);
        } catch (Exception e) {
            throw new RuntimeException("Key derivation failed", e);
        }
    }

    /**
     * Decrypts an uploaded blob. Returns the plaintext or throws on failure.
     * 
     * @param encryptedBlob The raw bytes of the uploaded encrypted blob
     * @return DecryptionResult containing status and optional plaintext
     */
    public DecryptionResult decryptBlob(byte[] encryptedBlob) {
        if (encryptedBlob == null || encryptedBlob.length < IV_LENGTH + BLOCK_SIZE + HMAC_LENGTH) {
            return DecryptionResult.error("INVALID_FORMAT", "Blob too short");
        }

        // Extract components
        byte[] iv = Arrays.copyOfRange(encryptedBlob, 0, IV_LENGTH);
        byte[] ciphertext = Arrays.copyOfRange(encryptedBlob, IV_LENGTH, encryptedBlob.length - HMAC_LENGTH);
        byte[] providedHmac = Arrays.copyOfRange(encryptedBlob, encryptedBlob.length - HMAC_LENGTH, encryptedBlob.length);

        // Verify integrity before decryption
        byte[] computedHmac = computeHmac(iv, ciphertext);
        if (!verifyHmac(computedHmac, providedHmac)) {
            return DecryptionResult.error("INTEGRITY_FAILURE", "HMAC verification failed");
        }

        // Decrypt
        try {
            byte[] plaintext = performDecryption(iv, ciphertext);
            return DecryptionResult.success(plaintext);
        } catch (Exception e) {
            return handleDecryptionError(e);
        }
    }

    private byte[] computeHmac(byte[] iv, byte[] ciphertext) {
        try {
            javax.crypto.Mac mac = javax.crypto.Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(hmacKey, "HmacSHA256"));
            mac.update(iv);
            mac.update(ciphertext);
            return mac.doFinal();
        } catch (Exception e) {
            throw new RuntimeException("HMAC computation failed", e);
        }
    }

    private boolean verifyHmac(byte[] computed, byte[] provided) {
        return MessageDigest.isEqual(computed, provided);
    }

    private byte[] performDecryption(byte[] iv, byte[] ciphertext) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        SecretKeySpec keySpec = new SecretKeySpec(encryptionKey, "AES");
        IvParameterSpec ivSpec = new IvParameterSpec(iv);
        cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);
        return cipher.doFinal(ciphertext);
    }

    private DecryptionResult handleDecryptionError(Exception e) {
        String message = e.getMessage();
        if (message != null && message.contains("pad")) {
            LOG.warning("Padding error during blob decryption: " + message);
            return DecryptionResult.error("DECRYPTION_FAILED", "Invalid padding detected");
        }
        LOG.warning("General decryption error: " + message);
        return DecryptionResult.error("DECRYPTION_FAILED", "Decryption error occurred");
    }

    /**
     * Batch processing endpoint for multi-part uploads.
     * Each part is independently encrypted and verified.
     */
    public BatchDecryptionResult decryptMultipartBlob(byte[][] parts) {
        BatchDecryptionResult batch = new BatchDecryptionResult();
        for (int i = 0; i < parts.length; i++) {
            long startTime = System.nanoTime();
            DecryptionResult result = decryptBlob(parts[i]);
            long elapsed = System.nanoTime() - startTime;
            batch.addResult(i, result, elapsed);
        }
        return batch;
    }

    // Result classes
    public static class DecryptionResult {
        private final boolean success;
        private final String errorCode;
        private final String errorMessage;
        private final byte[] plaintext;

        private DecryptionResult(boolean success, byte[] plaintext, String errorCode, String errorMessage) {
            this.success = success;
            this.plaintext = plaintext;
            this.errorCode = errorCode;
            this.errorMessage = errorMessage;
        }

        public static DecryptionResult success(byte[] plaintext) {
            return new DecryptionResult(true, plaintext, null, null);
        }

        public static DecryptionResult error(String code, String message) {
            return new DecryptionResult(false, null, code, message);
        }

        public boolean isSuccess() { return success; }
        public String getErrorCode() { return errorCode; }
        public String getErrorMessage() { return errorMessage; }
        public byte[] getPlaintext() { return plaintext; }
    }

    public static class BatchDecryptionResult {
        private final java.util.Map<Integer, DecryptionResult> results = new java.util.HashMap<>();
        private final java.util.Map<Integer, Long> timings = new java.util.HashMap<>();

        public void addResult(int index, DecryptionResult result, long elapsedNanos) {
            results.put(index, result);
            timings.put(index, elapsedNanos);
        }

        public DecryptionResult getResult(int index) { return results.get(index); }
        public Long getTiming(int index) { return timings.get(index); }
        public int size() { return results.size(); }
    }
}
